#!/usr/bin/env python3
"""Compute ground truth for CSX-269_Q2 from local package files."""

from __future__ import annotations

import csv
import json
import re
from datetime import date
from html import unescape
from pathlib import Path
from typing import Any
from urllib.parse import parse_qs, urlparse


TASK_ID = "CSX-269_Q2"
EVENT_ID = "CSX-269"
TASK_TYPE = "short_answer"
EVALUATION_MODE = "hybrid"
DIFFICULTY_LEVEL = "L3"

SOURCE_FILES = [
    "metadata/event.json",
    "metadata/files.csv",
    "data/event_reports/event_reports_001_Locked_anchor_NASA_Earth_Observatory.html",
    "data/remote_sensing/remote_sensing_002_pre.jpg",
    "data/remote_sensing/remote_sensing_003_event.jpg",
]


def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_dir() -> Path:
    return repo_root() / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID


def read_json(package: Path, rel_path: str) -> Any:
    return json.loads((package / rel_path).read_text(encoding="utf-8-sig"))


def read_text(package: Path, rel_path: str) -> str:
    return (package / rel_path).read_text(encoding="utf-8", errors="replace")


def read_manifest(package: Path) -> list[dict[str, str]]:
    with (package / "metadata" / "files.csv").open(newline="", encoding="utf-8-sig") as handle:
        return list(csv.DictReader(handle))


def require_manifest_paths(package: Path, rel_paths: list[str]) -> None:
    manifest_paths = {row["relative_path"] for row in read_manifest(package)}
    for rel_path in rel_paths:
        if rel_path.startswith("metadata/"):
            continue
        if rel_path not in manifest_paths:
            raise ValueError(f"Source file is not listed in metadata/files.csv: {rel_path}")


def manifest_row(package: Path, rel_path: str) -> dict[str, str]:
    for row in read_manifest(package):
        if row["relative_path"] == rel_path:
            return row
    raise ValueError(f"Missing manifest row for {rel_path}")


def snapshot_date_from_url(url: str) -> str:
    query = parse_qs(urlparse(url).query)
    values = query.get("TIME")
    if not values:
        raise ValueError(f"Snapshot URL has no TIME parameter: {url}")
    return values[0]


def parse_date(value: str) -> date:
    year, month, day = [int(part) for part in value.split("-")]
    return date(year, month, day)


def jpeg_size(path: Path) -> tuple[int, int]:
    data = path.read_bytes()
    index = 2
    if data[:2] != b"\xff\xd8":
        raise ValueError(f"Not a JPEG file: {path}")
    while index < len(data):
        while index < len(data) and data[index] == 0xFF:
            index += 1
        if index >= len(data):
            break
        marker = data[index]
        index += 1
        if marker in {0xD8, 0xD9}:
            continue
        segment_length = int.from_bytes(data[index : index + 2], "big")
        segment_start = index + 2
        if marker in {
            0xC0,
            0xC1,
            0xC2,
            0xC3,
            0xC5,
            0xC6,
            0xC7,
            0xC9,
            0xCA,
            0xCB,
            0xCD,
            0xCE,
            0xCF,
        }:
            height = int.from_bytes(data[segment_start + 1 : segment_start + 3], "big")
            width = int.from_bytes(data[segment_start + 3 : segment_start + 5], "big")
            return width, height
        index += segment_length
    raise ValueError(f"Could not read JPEG dimensions: {path}")


def strip_html(text: str) -> str:
    text = re.sub(r"<script\b.*?</script>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<style\b.*?</style>", " ", text, flags=re.IGNORECASE | re.DOTALL)
    text = re.sub(r"<[^>]+>", " ", text)
    text = unescape(text)
    return re.sub(r"\s+", " ", text).strip()


def build_rubric() -> dict[str, Any]:
    criteria = [
        {
            "name": "Correct final diagnosis",
            "points": 3,
            "description": "Identifies the best-supported diagnosis as regional smoke haze with attribution caution.",
            "partial_credit": "Award partial credit for naming smoke or fire haze without the attribution caveat, or for naming fires without the regional haze interpretation.",
        },
        {
            "name": "Key timing and image metrics",
            "points": 4,
            "description": "Reports the pre-event date, event-period date, 273-day gap, and 1024x768 image dimensions with correct units or formatting.",
            "partial_credit": "Award partial credit for two or three correct values, minor formatting differences, or a correct date pair with a small arithmetic error.",
        },
        {
            "name": "Remote-sensing interpretation",
            "points": 3,
            "description": "Explains that the event-period visual context supports regional smoke or haze rather than floodwater mapping, cyclone cloud tracking, or heat-only stress.",
            "partial_credit": "Award partial credit for a generic fire/smoke reading that lacks scale, timing, or contrast with competing hazard interpretations.",
        },
        {
            "name": "Impact-chain reasoning",
            "points": 3,
            "description": "Links smoke haze to decreased visibility, hazardous travel, flight cancellations, or broader transport disruption.",
            "partial_credit": "Award partial credit for mentioning visibility or air-quality effects without connecting them to operational disruption.",
        },
        {
            "name": "Attribution caution",
            "points": 3,
            "description": "States that satellite observations alone cannot assign parcel-level fire responsibility and that ground-based investigation is needed for such claims.",
            "partial_credit": "Award partial credit for a vague uncertainty warning that does not clearly explain the parcel-level attribution limit.",
        },
        {
            "name": "Rejects competing interpretations and overclaims",
            "points": 2,
            "description": "Avoids or rejects unsupported flood, cyclone, heat-only, burn-scar-only, legal blame, exact burned-area, loss, mortality, or causality claims.",
            "partial_credit": "Award partial credit for rejecting only some close alternatives or for avoiding overclaims without explaining why they are unsupported.",
        },
        {
            "name": "Structured concise response",
            "points": 2,
            "description": "Uses compact JSON with the requested fields and a concise interpretation tied to the event.",
            "partial_credit": "Award partial credit for a readable structured answer that omits one field or uses concise prose while preserving the required substance.",
        },
    ]
    total = sum(item["points"] for item in criteria)
    if total != 20:
        raise ValueError(f"Rubric must sum to 20 points, got {total}")
    return {"total_points": total, "criteria": criteria}


def main() -> None:
    package = package_dir()
    require_manifest_paths(package, SOURCE_FILES)

    event = read_json(package, "metadata/event.json")
    if event.get("package_id") != EVENT_ID:
        raise ValueError("Unexpected package_id in metadata/event.json")

    report_plain = strip_html(read_text(package, "data/event_reports/event_reports_001_Locked_anchor_NASA_Earth_Observatory.html"))
    report_lower = report_plain.lower()

    pre_rel = "data/remote_sensing/remote_sensing_002_pre.jpg"
    event_rel = "data/remote_sensing/remote_sensing_003_event.jpg"
    pre_row = manifest_row(package, pre_rel)
    event_row = manifest_row(package, event_rel)

    pre_date = snapshot_date_from_url(pre_row["url"])
    event_date = snapshot_date_from_url(event_row["url"])
    gap_days = (parse_date(event_date) - parse_date(pre_date)).days
    pre_size = jpeg_size(package / pre_rel)
    event_size = jpeg_size(package / event_rel)
    if pre_size != event_size:
        raise ValueError("Snapshot dimensions differ")

    text_flags = {
        "smoke_drifting_region_claim": "smoke drifting over the region" in report_lower,
        "visibility_flight_impact_claim": "decreased visibility" in report_lower and "cancellation of many flights" in report_lower,
        "satellite_alone_blame_caution": "using satellite observations alone to assign blame" in report_lower,
        "ground_investigation_needed": "ground-based investigations" in report_lower,
        "peat_fire_context": "peat" in report_lower and "fires" in report_lower,
    }

    if (
        text_flags["smoke_drifting_region_claim"]
        and text_flags["visibility_flight_impact_claim"]
        and text_flags["satellite_alone_blame_caution"]
        and gap_days > 200
    ):
        answer = "regional_smoke_haze_with_attribution_caution"
        role = [
            "event_period_smoke_context",
            "visibility_and_transport_disruption",
            "no_parcel_level_blame_from_imagery_alone",
        ]
        confidence = "high"
    else:
        answer = "ambiguous_remote_sensing_context"
        role = [
            "limited_visual_context",
            "impact_link_unclear",
            "attribution_requires_more_evidence",
        ]
        confidence = "low"

    snapshot_metrics = {
        "pre_snapshot_date": pre_date,
        "event_snapshot_date": event_date,
        "snapshot_gap_days": gap_days,
        "snapshot_dimensions": f"{pre_size[0]}x{pre_size[1]}",
        "pre_image_bytes": int(pre_row["bytes"]),
        "event_image_bytes": int(event_row["bytes"]),
    }

    computed_gt = {
        "schema_version": "crossscale_extreme_event_bench_v1",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": TASK_TYPE,
        "evaluation_mode": EVALUATION_MODE,
        "difficulty_level": DIFFICULTY_LEVEL,
        "primary_gt": {
            "answer_type": "diagnostic_label_plus_structured_brief",
            "answer": answer,
            "canonical_stance": (
                "The event-period visual context is regional Indonesian smoke haze with visibility and "
                "transport impacts; imagery alone cannot assign parcel-level fire responsibility."
            ),
            "required_metrics": {
                "pre_snapshot_date": pre_date,
                "event_snapshot_date": event_date,
                "snapshot_gap_days": gap_days,
                "snapshot_dimensions": f"{pre_size[0]}x{pre_size[1]}",
            },
            "required_claims": [
                "regional smoke or haze is the best visual diagnosis",
                "smoke haze links to visibility and transport disruption",
                "imagery alone cannot assign parcel-level fire responsibility",
                "the image pair is contextual, not a burned-area or legal-attribution product",
            ],
            "forbidden_claims": [
                "specific actors or ignition sources are responsible from snapshots alone",
                "the primary signal is floodwater, cyclone cloud tracking, or heat-only stress",
                "the snapshots quantify exact burned area, losses, mortality, or legal causality",
            ],
            "acceptable_variants": [
                "regional smoke-haze with attribution caution",
                "smoke transport and visibility disruption, not parcel-level blame",
                "fire-haze remote-sensing context with ground-investigation caveat",
            ],
        },
        "key_values": {
            "event_name": event.get("event_name"),
            "hazard_type": "drought_amplified_fire_smoke_haze",
            "classification_confidence": confidence,
            "expected_remote_sensing_role": role,
            "snapshot_metrics": snapshot_metrics,
            "text_claim_flags": text_flags,
            "classification_rule": {
                "requires_smoke_region_claim": True,
                "requires_visibility_transport_impact": True,
                "requires_satellite_attribution_caution": True,
                "minimum_snapshot_gap_days": 200,
            },
        },
        "rubric": build_rubric(),
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": SOURCE_FILES,
        },
    }

    output_path = Path(__file__).resolve().parent / "computed_gt.json"
    output_path.write_text(json.dumps(computed_gt, indent=2, sort_keys=True) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
